<?php
function h($x){return htmlspecialchars((string)$x,ENT_QUOTES,'UTF-8');}
function rp($x){return 'Rp '.number_format($x,0,',','.');}
$kasAwal=30000000;
$tx=[
['Pembelian bahan baku secara kredit',8000000,'Persediaan','Utang Usaha',0],
['Pembayaran utang pemasok',3000000,'Utang Usaha','Kas',-3000000],
['Penjualan produk secara kredit',12000000,'Piutang Usaha','Penjualan',0],
['Penerimaan pembayaran pelanggan',5000000,'Kas','Piutang Usaha',5000000],
['Pembayaran biaya operasional tunai',1500000,'Beban Operasional','Kas',-1500000]];
$kas=$kasAwal;foreach($tx as $t)$kas+=$t[4];
$produk=300;$grossA=900;$grossB=600;$netA=max(0,$grossA-400-100);$netB=max(0,$grossB-250);
$orderQty=10;$stok=15;$orderTotal=$orderQty*250000;
?>
